	private delegate bool NameResolver( string text, out uint id );
	private static bool AddIdentifiers( HashSet<int> destination, string? text, out string? error ) { error = null; if ( string.IsNullOrWhiteSpace( text ) ) { error = "empty identifier list"; return false; } foreach ( var token in SplitList( text ) ) { if ( !int.TryParse( token, NumberStyles.None, CultureInfo.InvariantCulture, out var id ) || 0 > id ) { error = $"invalid identifier '{token}'"; return false; } destination.Add( id ); } return true; }
