	private static void AddStrings( HashSet<string> destination, string? text ) { if ( null == text ) return; foreach ( var token in SplitList( text ) ) destination.Add( token ); }
	private static IEnumerable<string> SplitList( string text ) => text.Split( new[] { ',', ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries );
