	private static string ProgramName( ProcMatchCommandMode mode ) => mode switch { ProcMatchCommandMode.Pgrep => "pgrep", ProcMatchCommandMode.Pkill => "pkill", _ => "pidwait" };
	private static string Usage( ProcMatchCommandMode mode ) { var name = ProgramName( mode ); var modeOptions = mode switch { ProcMatchCommandMode.Pgrep => """
 -d, --delimiter <string> specify output delimiter
 -l, --list-name          list PID and process name
 -a, --list-full          list PID and full command line
     --quiet              suppress normal output
 -v, --inverse            negate matching
 -w, --lightweight        list Linux lightweight tasks
""", ProcMatchCommandMode.Pkill => """
 -<sig>                   signal to send by number or name
 -q, --queue <value>      queue integer signal value
 -e, --echo               display what is killed
 -m, --mrelease           release process memory after kill
""", _ => """
 -e, --echo               display PIDs before waiting
""" }; return $"""
Usage:
 {name} [options] <pattern>

Options:
{modeOptions} -c, --count              count matching processes
 -f, --full               use full process name to match
 -g, --pgroup <PGID,...>  match listed process group IDs
 -G, --group <GID,...>    match real group IDs or names
 -i, --ignore-case        match case insensitively
 -n, --newest             select most recently started
 -o, --oldest             select least recently started
 -O, --older <seconds>    select processes older than seconds
 -p, --pid <PID,...>      match listed process IDs
 -P, --parent <PPID,...>  match listed parent process IDs
 -s, --session <SID,...>  match listed session IDs
 -t, --terminal <tty,...> match controlling terminals
 -u, --euid <ID,...>      match effective user IDs or names
 -U, --uid <ID,...>       match real user IDs or names
 -x, --exact              match command name exactly
 -F, --pidfile <file>     read PID from file
 -L, --logpidfile         fail if pidfile is not locked
 -r, --runstates <state>  match Linux process states
 -A, --ignore-ancestors   exclude ancestors of this command
     --signal <sig>        signal used by pkill/--require-handler
 -H, --require-handler    match only processes catching signal
     --cgroup <name,...>  match cgroup v2 paths
     --ns <PID>           match Linux namespaces of PID
     --nslist <list>      limit compared namespaces
     --env <name[=value]> match process environment
